package br.com.brindespro.security;
import jakarta.servlet.http.*;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.security.authentication.*;import org.springframework.security.core.Authentication;import org.springframework.security.core.context.*;import org.springframework.security.web.context.SecurityContextRepository;import org.springframework.security.web.csrf.CsrfToken;import org.springframework.security.web.authentication.logout.SecurityContextLogoutHandler;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthenticationManager manager;private final SecurityContextRepository contexts;private final AdminUserRepository users;public AuthController(AuthenticationManager manager,SecurityContextRepository contexts,AdminUserRepository users){this.manager=manager;this.contexts=contexts;this.users=users;}public record Login(@Email String email,@NotBlank String password){}public record UserDto(String name){}public record TokenDto(String token){}
 @GetMapping("/csrf") public TokenDto csrf(CsrfToken token){return new TokenDto(token.getToken());}
 @PostMapping("/login") public UserDto login(@RequestBody Login login,HttpServletRequest request,HttpServletResponse response){try{Authentication auth=manager.authenticate(new UsernamePasswordAuthenticationToken(login.email(),login.password()));SecurityContext context=SecurityContextHolder.createEmptyContext();context.setAuthentication(auth);SecurityContextHolder.setContext(context);contexts.saveContext(context,request,response);return new UserDto(users.findByEmail(auth.getName()).orElseThrow().name);}catch(BadCredentialsException e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"E-mail ou senha inválidos.");}}
 @GetMapping("/me") public UserDto me(Authentication authentication){return new UserDto(users.findByEmail(authentication.getName()).orElseThrow().name);}
 @PostMapping("/logout") public void logout(HttpServletRequest request,HttpServletResponse response,Authentication authentication){new SecurityContextLogoutHandler().logout(request,response,authentication);}
}
